const std = @import("std");
pub const upstream_version = "5.9.4";
pub const Error = error{ OutOfMemory, InvalidDocument, UnsupportedValue, UnsupportedString, InvalidHandle, InvalidType, InvalidReducerName, CallbackError, DepthLimit };
pub const Handle = enum(u32) { _ };
pub const Value = union(enum) {
    null,
    undefined,
    boolean: bool,
    number: f64,
    string: []const u8,
    bigint: []const u8,
    ref: Handle,
};
pub const Property = struct { key: []const u8, value: Value };
pub const Element = struct { index: u32, value: Value };
pub const Entry = struct { key: Value, value: Value };
pub const Object = struct { null_proto: bool, properties: std.ArrayList(Property) = .empty };
pub const Array = struct { length: u32, elements: std.ArrayList(Element) = .empty };
pub const RegExp = struct { source: []const u8, flags: []const u8 };
pub const Node = union(enum) {
    object: Object,
    array: Array,
    map: std.ArrayList(Entry),
    set: std.ArrayList(Value),
    date: i64,
    regexp: RegExp,
    array_buffer: []const u8,
    boxed: Value,
};

/// Owns all values made by its constructors, including parsed strings. Never copy
/// a live Graph. Handles belong to this graph and survive growth. Returned views
/// must not be retained across mutation. Release the graph once with deinit.
pub const Graph = struct {
    arena: std.heap.ArenaAllocator,
    nodes: std.ArrayList(Node) = .empty,

    pub fn init(gpa: std.mem.Allocator) Graph {
        return .{ .arena = .init(gpa) };
    }
    pub fn deinit(self: *Graph) void {
        self.arena.deinit();
        self.* = undefined;
    }
    pub fn allocator(self: *Graph) std.mem.Allocator {
        return self.arena.allocator();
    }
    pub fn string(self: *Graph, bytes: []const u8) Error!Value {
        if (!std.unicode.utf8ValidateSlice(bytes)) return error.UnsupportedString;
        return .{ .string = try self.allocator().dupe(u8, bytes) };
    }
    pub fn bigint(self: *Graph, digits: []const u8) Error!Value {
        if (!canonicalBigInt(digits)) return error.UnsupportedValue;
        return .{ .bigint = try self.allocator().dupe(u8, digits) };
    }
    fn add(self: *Graph, new_node: Node) Error!Value {
        if (self.nodes.items.len >= std.math.maxInt(u32)) return error.UnsupportedValue;
        const handle: Handle = @fromBackingInt(@intCast(@as(u32, @intCast(self.nodes.items.len))));
        try self.nodes.append(self.allocator(), new_node);
        return .{ .ref = handle };
    }
    pub fn object(self: *Graph, null_proto: bool) Error!Value {
        return self.add(.{ .object = .{ .null_proto = null_proto } });
    }
    pub fn array(self: *Graph, length: u32) Error!Value {
        return self.add(.{ .array = .{ .length = length } });
    }
    pub fn map(self: *Graph) Error!Value {
        return self.add(.{ .map = .empty });
    }
    pub fn set(self: *Graph) Error!Value {
        return self.add(.{ .set = .empty });
    }
    pub fn date(self: *Graph, millis: i64) Error!Value {
        if (millis < -8640000000000000 or millis > 8640000000000000) return error.UnsupportedValue;
        return self.add(.{ .date = millis });
    }
    pub fn regexp(self: *Graph, source: []const u8, flags: []const u8) Error!Value {
        if (!std.unicode.utf8ValidateSlice(source)) return error.UnsupportedString;
        var canonical: [8]u8 = undefined;
        const len = try canonicalFlags(flags, &canonical);
        const a = self.allocator();
        return self.add(.{ .regexp = .{ .source = try a.dupe(u8, source), .flags = try a.dupe(u8, canonical[0..len]) } });
    }
    pub fn arrayBuffer(self: *Graph, bytes: []const u8) Error!Value {
        return self.add(.{ .array_buffer = try self.allocator().dupe(u8, bytes) });
    }
    pub fn boxed(self: *Graph, value: Value) Error!Value {
        switch (value) {
            .boolean, .number, .string, .bigint => {},
            else => return error.UnsupportedValue,
        }
        try self.validate(value);
        return self.add(.{ .boxed = value });
    }
    pub fn validate(self: *const Graph, value: Value) Error!void {
        switch (value) {
            .ref => |h| {
                if (@backingInt(h) >= self.nodes.items.len) return error.InvalidHandle;
            },
            .string => |s| {
                if (!std.unicode.utf8ValidateSlice(s)) return error.UnsupportedString;
            },
            .bigint => |s| {
                if (!canonicalBigInt(s)) return error.UnsupportedValue;
            },
            else => {},
        }
    }
    pub fn node(self: *const Graph, value: Value) Error!Node {
        if (value != .ref) return error.InvalidType;
        try self.validate(value);
        return self.nodes.items[@backingInt(value.ref)];
    }
    fn nodePtr(self: *Graph, value: Value) Error!*Node {
        if (value != .ref) return error.InvalidType;
        try self.validate(value);
        return &self.nodes.items[@backingInt(value.ref)];
    }
    /// Properties enumerate in JS order: array-index keys first, numerically,
    /// followed by other keys in insertion order. __proto__ is not supported.
    pub fn put(self: *Graph, target: Value, key: []const u8, value: Value) Error!void {
        try self.validate(value);
        if (!std.unicode.utf8ValidateSlice(key)) return error.UnsupportedString;
        if (std.mem.eql(u8, key, "__proto__")) return error.UnsupportedValue;
        const n = try self.nodePtr(target);
        if (n.* != .object) return error.InvalidType;
        for (n.object.properties.items) |*p| if (std.mem.eql(u8, p.key, key)) {
            p.value = value;
            return;
        };
        const a = self.allocator();
        const copy = try a.dupe(u8, key);
        var pos = n.object.properties.items.len;
        if (arrayIndex(key)) |index| {
            pos = 0;
            while (pos < n.object.properties.items.len) : (pos += 1) {
                const other = arrayIndex(n.object.properties.items[pos].key) orelse break;
                if (index < other) break;
            }
        }
        try n.object.properties.insert(a, pos, .{ .key = copy, .value = value });
    }
    pub fn remove(self: *Graph, target: Value, key: []const u8) Error!bool {
        const n = try self.nodePtr(target);
        if (n.* != .object) return error.InvalidType;
        for (n.object.properties.items, 0..) |p, i| if (std.mem.eql(u8, p.key, key)) {
            _ = n.object.properties.orderedRemove(i);
            return true;
        };
        return false;
    }
    pub fn get(self: *const Graph, target: Value, key: []const u8) Error!?Value {
        const n = try self.node(target);
        if (n != .object) return error.InvalidType;
        for (n.object.properties.items) |p| if (std.mem.eql(u8, p.key, key)) return p.value;
        return null;
    }
    pub fn arrayPut(self: *Graph, target: Value, index: u32, value: Value) Error!void {
        try self.validate(value);
        const n = try self.nodePtr(target);
        if (n.* != .array) return error.InvalidType;
        if (index >= n.array.length) return error.InvalidType;
        if (n.array.elements.items.len == 0 or n.array.elements.items[n.array.elements.items.len - 1].index < index) {
            try n.array.elements.append(self.allocator(), .{ .index = index, .value = value });
            return;
        }
        var pos: usize = 0;
        while (pos < n.array.elements.items.len and n.array.elements.items[pos].index < index) : (pos += 1) {}
        if (pos < n.array.elements.items.len and n.array.elements.items[pos].index == index) {
            n.array.elements.items[pos].value = value;
            return;
        }
        try n.array.elements.insert(self.allocator(), pos, .{ .index = index, .value = value });
    }
    /// null means a hole; .undefined means an explicitly populated undefined.
    pub fn arrayGet(self: *const Graph, target: Value, index: u32) Error!?Value {
        const n = try self.node(target);
        if (n != .array or index >= n.array.length) return error.InvalidType;
        for (n.array.elements.items) |e| {
            if (e.index == index) return e.value;
            if (e.index > index) break;
        }
        return null;
    }
    pub fn mapPut(self: *Graph, target: Value, key: Value, value: Value) Error!void {
        try self.validate(key);
        try self.validate(value);
        const n = try self.nodePtr(target);
        if (n.* != .map) return error.InvalidType;
        for (n.map.items) |*e| if (equal(e.key, key)) {
            e.value = value;
            return;
        };
        try n.map.append(self.allocator(), .{ .key = normalizeZero(key), .value = value });
    }
    pub fn setAdd(self: *Graph, target: Value, value: Value) Error!void {
        try self.validate(value);
        const n = try self.nodePtr(target);
        if (n.* != .set) return error.InvalidType;
        for (n.set.items) |v| if (equal(v, value)) return;
        try n.set.append(self.allocator(), normalizeZero(value));
    }
};

pub fn equal(a: Value, b: Value) bool {
    if (std.meta.activeTag(a) != std.meta.activeTag(b)) return false;
    return switch (a) {
        .null, .undefined => true,
        .boolean => |v| v == b.boolean,
        .number => |v| v == b.number or (std.math.isNan(v) and std.math.isNan(b.number)),
        .string => |v| std.mem.eql(u8, v, b.string),
        .bigint => |v| std.mem.eql(u8, v, b.bigint),
        .ref => |v| v == b.ref,
    };
}
fn normalizeZero(v: Value) Value {
    return if (v == .number and v.number == 0) .{ .number = 0 } else v;
}
pub fn canonicalBigInt(s: []const u8) bool {
    if (std.mem.eql(u8, s, "0")) return true;
    const digits = if (s.len > 0 and s[0] == '-') s[1..] else s;
    if (digits.len == 0 or digits[0] < '1' or digits[0] > '9') return false;
    for (digits) |c| if (c < '0' or c > '9') return false;
    return true;
}
pub fn arrayIndex(s: []const u8) ?u32 {
    if (s.len == 0 or s.len > 10 or (s.len > 1 and s[0] == '0')) return null;
    for (s) |c| if (c < '0' or c > '9') return null;
    const n = std.fmt.parseInt(u32, s, 10) catch return null;
    return if (n == std.math.maxInt(u32)) null else n;
}
fn canonicalFlags(flags: []const u8, out: *[8]u8) Error!usize {
    const order = "dgimsuvy";
    var seen: [8]bool = @splat(false);
    for (flags) |flag| {
        const i = std.mem.indexOfScalar(u8, order, flag) orelse return error.UnsupportedValue;
        if (seen[i]) return error.UnsupportedValue;
        seen[i] = true;
    }
    if (seen[5] and seen[6]) return error.UnsupportedValue;
    var len: usize = 0;
    for (order, seen) |c, yes| if (yes) {
        out[len] = c;
        len += 1;
    };
    return len;
}

pub const Reducer = struct { name: []const u8, context: ?*anyopaque = null, reduce: *const fn (?*anyopaque, *Graph, Value) Error!?Value };
pub const Reviver = struct { name: []const u8, context: ?*anyopaque = null, revive: *const fn (?*anyopaque, *Graph, Value) Error!Value };
pub const stringify = @import("encode.zig").stringify;
pub const parse = @import("decode.zig").parse;
pub const ParseResult = struct {
    graph: Graph,
    value: Value,
    pub fn deinit(self: *ParseResult) void {
        self.graph.deinit();
        self.* = undefined;
    }
};
/// Traversal limit is a resource bound, including reentrant custom callbacks.
pub const max_depth = 256;

const std = @import("std");
const d = @import("root.zig");
const p = @import("primitives.zig");
const Context = struct {
    pub fn hash(_: @This(), v: d.Value) u64 {
        var h = std.hash.Wyhash.init(@backingInt(std.meta.activeTag(v)));
        switch (v) {
            .null, .undefined => {},
            .boolean => |b| h.update(&.{@intFromBool(b)}),
            .number => |f| {
                const bits: u64 = @bitCast(f);
                h.update(std.mem.asBytes(&bits));
            },
            .string, .bigint => |s| h.update(s),
            .ref => |r| {
                const n: u32 = @backingInt(r);
                h.update(std.mem.asBytes(&n));
            },
        }
        return h.final();
    }
    pub fn eql(_: @This(), a: d.Value, b: d.Value) bool {
        return d.equal(a, b);
    }
};
pub fn truthy(v: d.Value) bool {
    return switch (v) {
        .null, .undefined => false,
        .boolean => |b| b,
        .number => |f| f != 0 and !std.math.isNan(f),
        .string => |s| s.len != 0,
        .bigint => |s| !std.mem.eql(u8, s, "0"),
        .ref => true,
    };
}
fn sentinel(v: d.Value) ?i64 {
    if (v == .undefined) return -1;
    if (v == .number) {
        if (std.math.isNan(v.number)) return -3;
        if (std.math.isInf(v.number)) return if (v.number > 0) -4 else -5;
        if (v.number == 0 and std.math.signbit(v.number)) return -6;
    }
    return null;
}
/// Returned bytes belong to gpa; caller frees them. The graph remains owned by
/// the caller. Reducers may allocate replacement nodes, but must not mutate
/// values/containers currently being traversed. Errors never transfer ownership.
pub fn stringify(gpa: std.mem.Allocator, graph: *d.Graph, value: d.Value, reducers: []const d.Reducer) d.Error![]u8 {
    for (reducers) |r| {
        if (!std.unicode.utf8ValidateSlice(r.name)) return error.InvalidReducerName;
        for (r.name) |c| if (c < 32 or c == '"' or c == '\\') return error.InvalidReducerName;
    }
    var arena: std.heap.ArenaAllocator = .init(gpa);
    defer arena.deinit();
    var e = Encoder{ .a = arena.allocator(), .graph = graph, .reducers = reducers };
    const root = try e.flatten(value, 0);
    var out: p.Buffer = .empty;
    errdefer out.deinit(gpa);
    if (root < 0) {
        try p.integer(&out, gpa, root);
    } else {
        try out.append(gpa, '[');
        for (e.slots.items, 0..) |slot, i| {
            if (i > 0) try out.append(gpa, ',');
            try out.appendSlice(gpa, slot);
        }
        try out.append(gpa, ']');
    }
    return out.toOwnedSlice(gpa);
}
const Encoder = struct {
    a: std.mem.Allocator,
    graph: *d.Graph,
    reducers: []const d.Reducer,
    slots: std.ArrayList([]const u8) = .empty,
    indices: std.HashMapUnmanaged(d.Value, i64, Context, 80) = .empty,
    fn flatten(self: *Encoder, v: d.Value, depth: usize) d.Error!i64 {
        try self.graph.validate(v);
        if (sentinel(v)) |n| return n;
        if (self.indices.get(v)) |n| return n;
        if (depth >= d.max_depth) return error.DepthLimit;
        const index: i64 = @intCast(self.slots.items.len);
        try self.slots.append(self.a, "");
        try self.indices.put(self.a, v, index);
        var b: p.Buffer = .empty;
        for (self.reducers) |r| {
            if (try r.reduce(r.context, self.graph, v)) |replacement| {
                try self.graph.validate(replacement);
                if (!truthy(replacement)) continue;
                const n = try self.flatten(replacement, depth + 1);
                try p.text(&b, self.a, "[");
                try p.quote(&b, self.a, r.name);
                try p.text(&b, self.a, ",");
                try p.integer(&b, self.a, n);
                try p.text(&b, self.a, "]");
                self.slots.items[@intCast(index)] = b.items;
                return index;
            }
        }
        switch (v) {
            .null => try p.text(&b, self.a, "null"),
            .undefined => unreachable,
            .boolean => |yes| try p.text(&b, self.a, if (yes) "true" else "false"),
            .number => |f| try p.number(&b, self.a, f),
            .string => |s| try p.quote(&b, self.a, s),
            .bigint => |s| {
                try p.text(&b, self.a, "[\"BigInt\",");
                try p.quote(&b, self.a, s);
                try p.text(&b, self.a, "]");
            },
            .ref => switch (try self.graph.node(v)) {
                .object => |obj| {
                    try p.text(&b, self.a, if (obj.null_proto) "[\"null\"" else "{");
                    for (obj.properties.items, 0..) |prop, i| {
                        if (obj.null_proto or i > 0) try p.text(&b, self.a, ",");
                        try p.quote(&b, self.a, prop.key);
                        try p.text(&b, self.a, if (obj.null_proto) "," else ":");
                        try p.integer(&b, self.a, try self.flatten(prop.value, depth + 1));
                    }
                    try p.text(&b, self.a, if (obj.null_proto) "]" else "}");
                },
                .array => |arr| {
                    var num: [16]u8 = undefined;
                    const digits = (std.fmt.bufPrint(&num, "{d}", .{arr.length}) catch unreachable).len;
                    const population: u64 = arr.elements.items.len;
                    const sparse = (@as(u64, arr.length) - population) * 3 > 4 + digits + population * (digits + 1);
                    if (sparse) {
                        try p.text(&b, self.a, "[-7,");
                        try p.integer(&b, self.a, arr.length);
                        for (arr.elements.items) |e| {
                            try p.text(&b, self.a, ",");
                            try p.integer(&b, self.a, e.index);
                            try self.edge(&b, e.value, depth);
                        }
                    } else {
                        try p.text(&b, self.a, "[");
                        var pos: usize = 0;
                        var i: u64 = 0;
                        while (i < arr.length) : (i += 1) {
                            if (i > 0) try p.text(&b, self.a, ",");
                            if (pos < arr.elements.items.len and arr.elements.items[pos].index == i) {
                                try p.integer(&b, self.a, try self.flatten(arr.elements.items[pos].value, depth + 1));
                                pos += 1;
                            } else try p.text(&b, self.a, "-2");
                        }
                    }
                    try p.text(&b, self.a, "]");
                },
                .map => |map| {
                    try p.text(&b, self.a, "[\"Map\"");
                    for (map.items) |e| {
                        try self.edge(&b, e.key, depth);
                        try self.edge(&b, e.value, depth);
                    }
                    try p.text(&b, self.a, "]");
                },
                .set => |set| {
                    try p.text(&b, self.a, "[\"Set\"");
                    for (set.items) |e| try self.edge(&b, e, depth);
                    try p.text(&b, self.a, "]");
                },
                .date => |ms| {
                    var buf: [27]u8 = undefined;
                    try p.text(&b, self.a, "[\"Date\",");
                    try p.quote(&b, self.a, p.dateString(&buf, ms));
                    try p.text(&b, self.a, "]");
                },
                .regexp => |re| {
                    try p.text(&b, self.a, "[\"RegExp\",");
                    try p.quote(&b, self.a, re.source);
                    if (re.flags.len > 0) {
                        try p.text(&b, self.a, ",");
                        try p.quote(&b, self.a, re.flags);
                    }
                    try p.text(&b, self.a, "]");
                },
                .array_buffer => |bytes| {
                    const n = std.base64.standard.Encoder.calcSize(bytes.len);
                    const buf = try self.a.alloc(u8, n);
                    _ = std.base64.standard.Encoder.encode(buf, bytes);
                    try p.text(&b, self.a, "[\"ArrayBuffer\",");
                    try p.quote(&b, self.a, buf);
                    try p.text(&b, self.a, "]");
                },
                .boxed => |unboxed| {
                    try p.text(&b, self.a, "[\"Object\"");
                    try self.edge(&b, unboxed, depth);
                    try p.text(&b, self.a, "]");
                },
            },
        }
        self.slots.items[@intCast(index)] = b.items;
        return index;
    }
    fn edge(self: *Encoder, b: *p.Buffer, v: d.Value, depth: usize) d.Error!void {
        try p.text(b, self.a, ",");
        try p.integer(b, self.a, try self.flatten(v, depth + 1));
    }
};

const std = @import("std");
const Error = @import("root.zig").Error;
pub const Buffer = std.ArrayList(u8);
pub fn text(b: *Buffer, a: std.mem.Allocator, s: []const u8) Error!void {
    try b.appendSlice(a, s);
}
pub fn integer(b: *Buffer, a: std.mem.Allocator, n: anytype) Error!void {
    var buf: [32]u8 = undefined;
    try text(b, a, std.fmt.bufPrint(&buf, "{d}", .{n}) catch unreachable);
}
pub fn quote(b: *Buffer, a: std.mem.Allocator, s: []const u8) Error!void {
    if (!std.unicode.utf8ValidateSlice(s)) return error.UnsupportedString;
    try b.append(a, '"');
    var i: usize = 0;
    var start: usize = 0;
    while (i < s.len) : (i += 1) {
        var replacement: ?[]const u8 = switch (s[i]) {
            '"' => "\\\"",
            '\\' => "\\\\",
            '<' => "\\u003C",
            '\n' => "\\n",
            '\r' => "\\r",
            '\t' => "\\t",
            8 => "\\b",
            12 => "\\f",
            else => null,
        };
        var hex: [6]u8 = undefined;
        var width: usize = 1;
        if (replacement == null and s[i] < 32) {
            replacement = std.fmt.bufPrint(&hex, "\\u00{x:0>2}", .{s[i]}) catch unreachable;
        } else if (std.mem.startsWith(u8, s[i..], "\xe2\x80\xa8")) {
            replacement = "\\u2028";
            width = 3;
        } else if (std.mem.startsWith(u8, s[i..], "\xe2\x80\xa9")) {
            replacement = "\\u2029";
            width = 3;
        }
        if (replacement) |r| {
            try text(b, a, s[start..i]);
            try text(b, a, r);
            i += width - 1;
            start = i + 1;
        }
    }
    try text(b, a, s[start..]);
    try b.append(a, '"');
}
// Zig's shortest-roundtrip Ryu digits, with ECMAScript Number::toString layout.
pub fn number(b: *Buffer, a: std.mem.Allocator, f: f64) Error!void {
    if (!std.math.isFinite(f)) return error.UnsupportedValue;
    if (f == 0) return text(b, a, "0");
    if (f < 0) try b.append(a, '-');
    var buf: [64]u8 = undefined;
    const scientific = std.fmt.float.render(&buf, @abs(f), .{ .mode = .scientific }) catch unreachable;
    const e = std.mem.indexOfScalar(u8, scientific, 'e').?;
    const exp = std.fmt.parseInt(i32, scientific[e + 1 ..], 10) catch unreachable;
    var digits_buf: [32]u8 = undefined;
    var k: usize = 0;
    for (scientific[0..e]) |c| if (c != '.') {
        digits_buf[k] = c;
        k += 1;
    };
    const digits = digits_buf[0..k];
    const n = exp + 1;
    if (n > 0 and n <= 21) {
        const pos: usize = @intCast(n);
        if (k <= pos) {
            try text(b, a, digits);
            try b.appendNTimes(a, '0', pos - k);
        } else {
            try text(b, a, digits[0..pos]);
            try b.append(a, '.');
            try text(b, a, digits[pos..]);
        }
    } else if (n > -6 and n <= 0) {
        try text(b, a, "0.");
        try b.appendNTimes(a, '0', @intCast(-n));
        try text(b, a, digits);
    } else {
        try b.append(a, digits[0]);
        if (k > 1) {
            try b.append(a, '.');
            try text(b, a, digits[1..]);
        }
        try text(b, a, if (exp >= 0) "e+" else "e-");
